import { cn } from "cn";

/**
 * 失败消息支持的动效预设（ADR 0021）。缺省 `fade`。
 * - `fade`：出现时淡入，150ms。
 * - `slide-up`：出现时从下方 16px 升起并淡入，220ms。
 * - `none`：直接出现。
 */
type FormErrorMotion = "none" | "fade" | "slide-up";

/**
 * 表单或浮层内的失败消息，放在页脚按钮上方。`message` 为空时不渲染。
 * 出现时按 `motion` 入场（基础层的 `@starting-style`）；换成另一条消息时重挂，再入场一次。
 */
function FormError({
  message,
  id,
  motion = "fade",
  className,
}: {
  message?: string | null;
  id?: string;
  motion?: FormErrorMotion;
  className?: string;
}) {
  if (!message) return null;
  return (
    <p
      key={message}
      role="alert"
      id={id}
      data-slot="form-error"
      data-motion={motion === "none" ? undefined : motion}
      className={cn("text-destructive-subtle-foreground text-xs", className)}
    >
      {message}
    </p>
  );
}

export { FormError, type FormErrorMotion };
